#include <bits/stdc++.h>
using namespace std;

int main(){
    long long a,b,c,l;
    cin>>a>>b>>c>>l;
    long long total=0;
    for(long long d=0;d<=l;d++) total += (d+1)*(d+2)/2;
    long long bad=0;
    long long arr[3][3]={{a,b,c},{b,a,c},{c,a,b}};
    for(int i=0;i<3;i++){
        long long x=arr[i][0], y=arr[i][1], z=arr[i][2];
        for(long long d=0;d<=l;d++){
            long long m = min(l-d, x+d-y-z);
            if(m>=0) bad += (m+1)*(m+2)/2;
        }
    }
    cout << total-bad << endl;
    return 0;
}
